theorem integral_sameSideKernelMul_general_zero {x₁ x₂ : ℝ}
    (hx₁ : 0 < x₁) (hx₂ : 0 < x₂) {β₁ β₂ : ℝ}
    (hc : (((x₂ - x₁ : ℝ) : ℂ) + I * ((β₂ - β₁ : ℝ) : ℂ)) ≠ 0) :
    (∫ t : ℝ, ((x₁ : ℂ) + I * ((t + β₁ : ℝ) : ℂ))⁻¹ *
      ((x₂ : ℂ) + I * ((t + β₂ : ℝ) : ℂ))⁻¹) = 0

